button.primary { background: #2563eb; color: #fff; border: none; border-radius: 4px; padding: 7px 14px; }
button.secondary { background: #e5e9f0; border: none; border-radius: 4px; padding: 5px 10px; }
button:disabled { opacity: 0.5; cursor: default; }
.notice { margin: 0; padding: 10px 20px; background: #fde68a; color: #78350f; }
.notice.error { background: #fecaca; color: #7f1d1d; }
.card-panel { background: #fff; border-radius: 8px; padding: 20px; max-width: 420px; margin: 40px auto; box-shadow: 0 1px 3px rgba(0,0,0,.1); }
.card-panel h2 { margin-top: 0; }
.stack { display: flex; flex-direction: column; gap: 10px; }
.row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.boards-list { list-style: none; padding: 0; margin: 0 0 20px; display: grid; gap: 10px; max-width: 700px; }
.boards-list a { display: flex; justify-content: space-between; background: #fff; padding: 14px 16px; border-radius: 8px; text-decoration: none; color: inherit; box-shadow: 0 1px 2px rgba(0,0,0,.08); }
.muted { color: #6b7280; font-size: 13px; }
.board-header { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 14px; flex-wrap: wrap; gap: 8px; }
.board-header h1 { margin: 0; font-size: 22px; }
.columns { display: flex; gap: 14px; align-items: flex-start; overflow-x: auto; padding-bottom: 10px; }
.column { background: #e4e8ef; border-radius: 8px; width: 270px; min-width: 270px; padding: 10px; display: flex; flex-direction: column; gap: 8px; }
.column.drop-target { outline: 2px dashed #2563eb; }
.column-head { display: flex; justify-content: space-between; align-items: center; font-weight: 600; }
.column-head .count { font-weight: 400; font-size: 13px; color: #374151; }
.column-head .count.full { color: #b91c1c; font-weight: 700; }
.cards { display: flex; flex-direction: column; gap: 8px; min-height: 30px; }
.kcard { background: #fff; border-radius: 6px; padding: 10px; box-shadow: 0 1px 2px rgba(0,0,0,.1); cursor: grab; }
.kcard.dragging { opacity: 0.5; }
.kcard .title { font-weight: 600; margin-bottom: 4px; word-break: break-word; }
.kcard .desc { font-size: 13px; color: #4b5563; margin-bottom: 6px; white-space: pre-wrap; word-break: break-word; }
.kcard .meta { font-size: 12px; color: #6b7280; margin-bottom: 6px; }
.kcard .moves { display: flex; gap: 4px; align-items: center; flex-wrap: wrap; }
.kcard .moves select { font-size: 12px; padding: 2px 4px; }
.add-card { display: flex; flex-direction: column; gap: 6px; }
.add-card input { width: 100%; }
.error-text { color: #b91c1c; font-size: 13px; }

