  setWhoami();
  const hash = location.hash || '#/';
  const boardMatch = /^#\/boards\/([^/]+)$/.exec(hash);
  if (hash === '#/login' || (!token && hash !== '#/register')) {
    if (!token) return renderAuth(hash === '#/register' ? 'register' : 'login');
  }
